function photo(name,rect=[0,0,1,1],alt='',cls='',ratio){const [x,y,w,h]=rect,[nw,nh]=imageSizes[name]||[1500,1000],native=nw*w/(nh*h);return `<figure data-crop="${rect.join(',')}" data-fit="contain" class="crop ${cls}" style="--native-ratio:${native};--ratio:${ratio||native};--iw:${100/w}%;--ih:${100/h}%;--ix:${-x/w*100}%;--iy:${-y/h*100}%"><img decoding="async" src="${A+name}.webp" alt="${esc(alt)}" style="clip-path:inset(${y*100}% ${Math.max(0,1-x-w)*100}% ${Math.max(0,1-y-h)*100}% ${x*100}%)" loading="lazy"></figure>`;}
function hero(tag,title,text,img,rect,extra='',className=''){const [nw,nh]=imageSizes[img],[x,y,w,h]=rect,native=nw*w/(nh*h);return `<section class="hero ${className}"><div class="hero-copy">${eye(tag)}<h1>${title}</h1><p class="lede">${text}</p>${extra}</div><div class="hero-art" style="--hero-ratio:${native}">${photo(img,rect,tag+' editorial image')}</div></section>`;}
