function recipesPage(){return hero('RECIPES BY PROCTOR & ALLAN','A little inspiration.<br>A lot to enjoy.','Breakfast favourites, simple snacks and bakes worth sharing.','recipes-hero',[.44,.14,.56,.83],btn('#recipe-collection','Discover the recipes'))+`<section class="section" id="recipe-collection">${sectionHead('MADE WITH YOUR FAVOURITES','Something delicious for every day.','Simple ideas with our corn flakes, oats and cake mixes.')}<p class="note">Estimated total times · preparation + cooking</p><div class="catalogue-tools"><div class="filter-row" aria-label="Filter recipes">${['All recipes','Corn Flakes','Oats','Cake Mix'].map((x,i)=>`<button data-recipe-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><label class="search-label">Search recipes<input class="search" id="recipe-search" type="search" placeholder="Recipe or ingredient…"></label></div><div class="recipe-grid" id="recipes-grid">${R.map(recipeCard).join('')}</div><p class="note" role="status" id="recipe-status">Times are estimates. Follow the full recipe and your current pack instructions.</p></section>`+restoredSlide("pancakes",`<section class="section"><div class="recipe-detail">${recipePhoto(R[1])}<div>${eye('IN THE KITCHEN')}<h2>Banana oat pancakes</h2><p class="lede">Made with Proctor & Allan White Oats</p><p class="meta">Prep 10 min · Cook 15 min · Serves 2</p><h3 style="margin-top:30px">What you’ll need</h3><ul>${R[1].ingredients.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Let’s make it</h3><ol>${R[1].steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="note">Estimated timings. ${R[1].allergens}</p></div></div></section>`)+tips();}
function tips(){return `<section class="section">${sectionHead('A LITTLE KNOW-HOW','Little tips. Better results.','Small details to help you get more from every recipe.')}<div class="ingredient-grid">${[['Blend for a finer texture.','For recipes calling for oat flour, blend the oats finely before measuring.'],['Keep a little crunch.','Crush corn flakes lightly for coatings and toppings, rather than grinding them to powder.'],['Let the recipe guide you.','Preheat the oven and follow your cake mix pack for quantities and baking guidance.']].map(([h,p],i)=>`<article>${photo('tips',[i/3,.29,1/3,.40],h,'',1.5)}<h3 style="font-size:29px">${h}</h3><p>${p}</p></article>`).join('')}</div></section>`;}
function recipeDetail(r){return `<section class="section detail-page"><div class="breadcrumb"><a href="/recipes">Recipes</a> / ${r.name}</div><div class="recipe-detail">${recipePhoto(r)}<article>${eye('THE PROCTOR & ALLAN KITCHEN')}<h1>${r.name}</h1><p class="lede">Made with ${r.product}</p><p class="meta">Prep ${r.prep} min · ${r.cook?'Cook '+r.cook+' min':'No cooking'} · Serves ${r.serves}</p><h2>What you’ll need</h2><ul>${r.ingredients.map(x=>`<li>${x}</li>`).join('')}</ul><h2>Let’s make it</h2><ol>${r.steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="note">${r.note||'Timings are estimates. Follow your current pack instructions.'}</p><p class="note">${r.allergens||'Check every ingredient and your current pack for allergen information.'}</p><button class="print-button" type="button" data-print>Print recipe</button></article></div></section>`;}
function story(){return hero('OUR STORY','A Kenyan story.<br>Still growing.','From our beginnings in Nakuru to a new chapter under Astitva Foods in 2026, discover the story behind Proctor & Allan.','story-hero',[.43,.09,.57,.87],cue('journey','Discover our journey'))+timeline()+chapter();}
const articles=[
{id:'food-labels',title:'Making sense of food labels',desc:'A guide to ingredients, serving information and nutrition values.',sections:[['Begin with the ingredient list','The ingredients tell you what goes into a food. Read them together with the allergen declaration on the current pack, especially when choosing for someone with an allergy.'],['Check the basis','Before comparing two foods, check whether the values refer to 100 g, a serving or the prepared food. Use the same basis for a fair comparison.'],['Read beyond one number','Look at energy, fibre, sugars, salt and other nutrients together. Product-specific information belongs on the current pack; ask our team if you need clarification.']]},
{id:'varied-breakfast',title:'Building a varied breakfast',desc:'Explore different foods, flavours and textures for your morning.',sections:[['Start with variety','Cereals or porridge can sit alongside other foods in your breakfast routine. Fruit, milk, yoghurt and suitable alternatives offer different flavours and textures.'],['Make it work for you','Choose combinations that fit your preferences, dietary needs and the time you have. A varied diet is about the pattern of what you eat, not one particular breakfast.'],['Know what you add','Milk, sweeteners, fruit and other toppings change the nutrients in your finished meal. Check labels and consider the whole bowl.']]},
{id:'grains',title:'A closer look at grains',desc:'Meet familiar ingredients behind cereals, oats and baking.',sections:[['Different grains, different foods','Maize, oats and wheat can be prepared in many ways. The process and other ingredients help shape the texture and character of the finished food.'],['Read the ingredients','A product name does not tell the whole story. Check the current ingredient list to understand which grains are present and whether a product is described as whole grain.'],['Explore the range','Our range includes maize corn flakes, whole oat products, porridge blends and wheat-based cake mixes. Product pages bring the available ingredient information together.']]},
{id:'your-bowl',title:'What goes into your bowl?',desc:'Consider the milk, fruit and other foods you add.',sections:[['The finished meal matters','Nutrition figures may describe a dry product rather than the bowl you eat. Any milk, yoghurt, fruit, nuts or sweetener you add contributes to the finished meal.'],['Choose your additions','Try different combinations and textures. Check the labels on milk alternatives and other additions rather than assuming that all options have the same nutrients.'],['Keep it clear','Use the serving information and ingredients on your current pack as your starting point. Consider your own needs and preferences when preparing your bowl.']]},
{id:'servings',title:'Servings and portions',desc:'Understand label information and what you serve.',sections:[['Two useful ideas','A serving on a label is the quantity used to describe the product’s nutrition information. Your portion is the amount you actually choose to eat.'],['Check before comparing','Look for the serving weight in grams and whether information is given per 100 g or per serving. Comparing the same quantity helps you understand differences.'],['Consider the full meal','The amount you serve and any additions affect the nutrients in the finished meal. A label serving is not a personalised recommendation.']]},
{id:'active-routine',title:'Food and an active routine',desc:'Make room for enjoyable meals and movement in everyday life.',sections:[['Find movement you enjoy','Walking, cycling, dancing and other forms of movement can have a place in an active routine. Choose activities that suit your ability and circumstances.'],['Food fits into the bigger picture','Enjoy a variety of foods and make time for meals that work for your day. A single cereal or ingredient is not a substitute for a varied diet.'],['Keep it personal','Your needs can change with age, activity and health. Seek individual guidance from a qualified professional if you need support with food or exercise choices.']]}
];
const articleRect=i=>[i%2?.513:.015,[.125,.432,.730][Math.floor(i/2)],.471,[.204,.197,.182][Math.floor(i/2)]];
function articleCard(a,i){return `<article class="article-card"><a href="/health-and-nutrition/${a.id}">${photo('articles',articleRect(i),a.title,'',1.78)}<h3>${a.title}</h3></a><p>${a.desc}</p>${link('/health-and-nutrition/'+a.id,'Explore article')}</article>`;}
function nutritionPage(){return hero('HEALTH & NUTRITION','Good food.<br>An active life.','Explore grains, understand your food and find inspiration for a varied, balanced lifestyle.','nutrition-hero',[.43,.09,.57,.88],cue('nutrition-articles','Discover the goodness within'))+`<section class="section" id="nutrition-articles"><div class="centre" style="margin-bottom:50px">${eye('HEALTH & NUTRITION')}<h2>Food knowledge for everyday life.</h2><p class="lede">Explore grains, breakfast and the information on your pack.</p></div><div class="article-grid">${articles.map(articleCard).join('')}</div></section>`;}
function articleDetail(a){return `<section class="section detail-page"><div class="article-body"><div class="breadcrumb"><a href="/health-and-nutrition">Health & Nutrition</a> / ${a.title}</div>${eye('EVERYDAY FOOD KNOWLEDGE')}<h1>${a.title}</h1><p class="lede">${a.desc}</p>${photo('articles',articleRect(articles.indexOf(a)),a.title,'',1.78)}${a.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<p class="note">General educational information. For product-specific ingredients and nutrition, read your current pack.</p><p class="note">Further reading: <a href="https://www.fda.gov/food/nutrition-facts-label/how-understand-and-use-nutrition-facts-label" target="_blank" rel="noopener">Understanding nutrition labels</a> · <a href="https://www.who.int/news-room/fact-sheets/detail/healthy-diet" target="_blank" rel="noopener">A varied diet</a></p></div></section>`;}
function farmers(){return hero('FARM TO TABLE','Every grain.<br>Part of a bigger story.','Explore the journey from the fields to food production, packaging and your table.','farm-hero',[.43,.09,.57,.89],cue('field','Follow the journey'))+`<div id="field">${split('WHERE THE JOURNEY BEGINS','The people behind<br>every harvest.','Before grain reaches a mill or a production line, it begins with the knowledge, patience and work of farmers.','farmer',[0,0,.55,.86],[['Growing','Preparing the land and tending the crop through the season.'],['Harvesting','Gathering mature grain for the next stage of its journey.'],['Looking ahead','Recognising the people whose work makes food possible.']])}</div>`+split('THE NEXT STAGE','From grain<br>to food.','Beyond the harvest, preparation, processing and packing shape the foods that reach your table.','manufacturing',[.48,0,.52,1],[['Ingredient preparation','Grains and other ingredients are prepared for the product being made.'],['Processing','Different foods call for different methods, from flaking and milling to blending.'],['Packing','Finished products are packed with information for storage and preparation.']],true)+split('QUALITY & CARE','Care at every stage.','A continued focus on the details that matter, from ingredients to the finished pack.','quality',[0,0,.56,1],[['Ingredient attention','Quality begins with attention to the materials used in each product.'],['Hygiene matters','Clean working practices are central to responsible food production.'],['Packaging with purpose','The finished pack brings together product protection, preparation guidance and useful information.']])+restoredSlide("journey-home-approved",split('TO YOUR TABLE','The journey<br>comes home.','From the fields and through production, the journey leads to the foods you choose for your home.','product-family',[.056,0,.924,1],[],false,`<p class="note">Corn flakes, oats, porridge and cake mixes—each with its own place in everyday life.</p>${btn('/products','Explore our foods')}<p class="note">Farm and production photography illustrates the food journey.</p>`),`<a class="approved-hotspot restored-journey-link" href="/products" aria-label="Explore our foods"></a>`);}
