function whereToBuy(){return hero('WHERE TO BUY','Your favourites.<br>Closer to you.','Find Proctor & Allan foods at supermarkets and retailers in Kenya.','buy-hero',[.43,.12,.57,.87],`<p class="note">Product ranges and pack sizes may vary by store.</p>${cue('retail-partners','Explore our retail partners')}`)+`<section class="section" id="retail-partners">${sectionHead('AT YOUR LOCAL SUPERMARKET','Find us where you shop.','Look for Proctor & Allan in the cereal and baking aisles.')}${retailerLogos()}<div class="retail-note"><h3>Availability varies by branch.</h3><p>Please check with your preferred store for current products and pack sizes.</p></div><p class="note" style="margin-top:45px">Looking for supply or distribution enquiries? <a href="/contact?topic=business">Contact our team →</a></p></section>`;}
