function contact(){return hero('CONTACT US','Good conversations.<br>New possibilities.','Questions about our foods, retail supply or international opportunities? We’d be glad to hear from you.','contact-hero',[.44,.12,.56,.87],`<p class="note">Based in Limuru, Kenya. Open to conversations near and far.</p>${cue('contact-form','Get in touch')}`)+`<section class="section" id="contact-form">${sectionHead('LET’S TALK','How can we help?','Send us your enquiry and help us direct it to the right team.')}<div class="contact-layout"><form class="contact-form" id="enquiry-form" action="https://formsubmit.co/info@proctorandallan.com" method="POST"><label>Enquiry type<select name="Enquiry type" id="enquiry-type"><option value="general">General enquiry</option><option value="feedback">Product feedback</option><option value="business">Business & distribution</option><option value="international">International enquiry</option></select></label><div class="field-row"><label>Full name *<input name="Name" autocomplete="name" required maxlength="120"></label><label>Email address *<input type="email" name="email" autocomplete="email" required maxlength="254"></label></div><div class="field-row"><label>Phone number<input type="tel" name="Phone" autocomplete="tel" maxlength="40"></label><label>Company / organisation<input name="Company" autocomplete="organization" maxlength="150"></label></div><div class="field-row"><label>Country *<input name="Country" autocomplete="country-name" required maxlength="90"></label><label>City / region<input name="City" autocomplete="address-level2" maxlength="120"></label></div><label>Subject *<input name="Subject" required maxlength="180"></label><label>Your message *<textarea name="Message" required minlength="10" maxlength="6000" placeholder="Tell us how we can help. For business enquiries, include your market and products of interest."></textarea></label><input type="text" name="_honey" style="display:none" tabindex="-1" autocomplete="off" aria-hidden="true"><input type="hidden" name="_subject" value="Proctor & Allan website enquiry"><input type="hidden" name="_template" value="table"><input type="hidden" name="_next" id="form-next"><label class="consent"><input type="checkbox" required name="Consent" value="Agreed"><span>I agree to the use of my details to respond to this enquiry. <a href="/privacy">Privacy notice</a></span></label><button class="btn" type="submit">Send enquiry <span aria-hidden="true">→</span></button><p class="note">Fields marked * are required.</p><p id="form-status" role="status"></p></form><aside class="contact-info"><h3>Speak to our team</h3><dl><div><dt>General enquiries</dt><dd><a href="mailto:info@proctorandallan.com">info@proctorandallan.com</a></dd></div><div><dt>Sales & international enquiries</dt><dd><a href="mailto:sales@proctorandallan.com">sales@proctorandallan.com</a></dd></div><div><dt>Call us</dt><dd><a href="tel:+254727065933">+254 727 065 933</a><a href="tel:+254722266161">+254 722 266 161</a></dd></div><div><dt>Find us</dt><dd>Manguo Road, Limuru, Kenya</dd></div></dl><p class="note">For product feedback, include the product name, pack size and batch details where available.</p></aside></div></section><section class="section" id="location">${sectionHead('OUR LOCATION','Find us in Limuru.','Proctor & Allan · Manguo Road, Limuru, Kenya')}<div class="map-layout"><div><h3>Factory location</h3><p>Manguo Road<br>Limuru, Kenya</p><p class="note">Please contact our team before arranging a visit.</p><p class="contacts"><a href="tel:+254727065933">+254 727 065 933</a><br><a href="mailto:info@proctorandallan.com">info@proctorandallan.com</a></p><a class="btn" href="${mapURL}" target="_blank" rel="noopener">Get directions ↗</a></div><div><iframe title="Google Maps: Proctor and Allan factory, Limuru" src="https://maps.google.com/maps?q=Proctor%20%26%20Allan%20(EA)%20Ltd%20Limuru&output=embed" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe><p class="caption">Proctor & Allan (EA) Ltd · Limuru · <a href="${mapURL}" target="_blank" rel="noopener">Open map ↗</a></p></div></div></section>`;}
let nutrition;
const tabs=['About','Ingredients & allergens','Nutrition','How to prepare'];
function productInfo(p,i){const n=nutrition.products[p.id];if(i===0)return `<h2>${p.name}, your way.</h2><p>${p.desc}</p><p>${p.prepare}</p>`;if(i===1)return `<h2>Ingredients & allergens</h2>${n.ingredients.length?`<h3>Ingredients</h3><p>${esc(n.ingredients.join(' '))}</p>`:'<p>Refer to the ingredient list on your current pack, or contact our team for the current specification.</p>'}<h3>Allergen information</h3><p>${n.allergens.length?esc(n.allergens.join('; ')):'Please check the current pack for the complete allergen declaration.'}</p>${p.id==='cake-mix'?'<p class="note">Wheat flour is an ingredient. The supplied specification also lists soya, milk and nuts; check the current variant’s label for the full declaration.</p>':''}${p.id==='nutririch-porridge'?'<p class="note">Soya is present in the ingredients. Check the current pack for the full allergen declaration.</p>':''}<p class="note">Always read the current pack before use, especially when choosing food for someone with an allergy.</p>`;if(i===2)return `<h2>Nutritional information</h2>${n.nutrients.length?`<table class="nutrition-table"><caption>${esc(n.basis)}</caption><thead><tr><th scope="col">Nutrient</th><th scope="col">Value</th></tr></thead><tbody>${n.nutrients.map(v=>`<tr><th scope="row">${esc(v.label)}</th><td>${esc(v.value)}</td></tr>`).join('')}</tbody></table>`:'<p>Nutrition values are not available here yet. Please refer to your current pack or ask our team for the product specification.</p>'}${n.pending&&n.nutrients.length?'<p class="note">Some values are being confirmed and are not shown here. Please refer to your current pack for the complete panel.</p>':''}<p class="note">${p.id==='baby-porridge'?'Specification: Kiddos Baby Porridge. ':''}Values relate to the product as described above; milk and other additions change the prepared meal.</p>`;return `<h2>Prepare & enjoy</h2><p>${p.prepare}</p><h3>Storage</h3><p>Follow the storage guidance and best-before date on your current pack. Keep the product protected after opening.</p>`;}
function productDetail(p){return `<section class="section detail-page"><div class="breadcrumb"><a href="/products">Our Foods</a> / ${p.name}</div><div class="product-overview"><div>${p.pack?`<img decoding="async" loading="lazy" class="pack" src="/assets/${p.pack}" alt="Official Proctor & Allan ${p.name} packaging">`:`<div class="empty-image">Nutririch<br>Porridge</div>`}</div><div>${eye('THE '+p.group.toUpperCase()+' COLLECTION')}<h1>${p.name}</h1><p class="lede">${p.desc}</p>${p.id==='cake-mix'?'<p class="note">Available in vanilla and chocolate.</p>':''}<div class="sizes" aria-label="Pack formats">${p.sizes.map(s=>`<span class="size">${s}</span>`).join('')}</div>${btn('/where-to-buy','Where to buy')}</div></div><div class="tabs" role="tablist" aria-label="Product information">${tabs.map((t,i)=>`<button id="tab-${i}" role="tab" aria-selected="${i===0}" aria-controls="product-panel" tabindex="${i===0?0:-1}" data-product-tab="${i}">${t}</button>`).join('')}</div><div class="tab-content" role="tabpanel" id="product-panel" aria-labelledby="tab-0" tabindex="0">${productInfo(p,0)}</div></section>`;}
function legal(kind){return `<section class="section detail-page"><article class="article-body">${eye('PROCTOR & ALLAN')}<h1>${kind==='privacy'?'Privacy notice':'Website terms'}</h1>${kind==='privacy'?`<h2>Contact enquiries</h2><p>When you complete our enquiry form, we use the details you provide to respond to your message and direct it to the appropriate team. Please only include information relevant to your enquiry.</p><h2>Form processing</h2><p>The enquiry form is processed by FormSubmit. Your submitted details are sent to our general or sales inbox according to your selected topic. Read <a href="https://formsubmit.co/privacy.pdf" target="_blank" rel="noopener">FormSubmit’s privacy information</a> for its processing practices.</p><h2>External content</h2><p>The contact page embeds Google Maps, which may receive technical information such as your IP address when loaded. This website also loads fonts from Google Fonts. Their own privacy policies apply.</p><h2>Get in touch</h2><p>For questions about the personal information in your enquiry, contact <a href="mailto:info@proctorandallan.com">info@proctorandallan.com</a>.</p>`:`<h2>Product information</h2><p>Our website introduces the range and provides general information. Packaging, formulations, sizes and availability may vary. Always read the current pack for ingredients, allergens, preparation, storage and the complete nutrition panel.</p><h2>Recipes and articles</h2><p>Recipe timings are estimates and may vary with equipment and quantities. Health and nutrition articles are general educational information, not individual medical advice.</p><h2>Photography</h2><p>Food and lifestyle photographs illustrate serving ideas and the brand story. Farm, production and professional scenes are illustrative; they do not document particular company sites, staff or suppliers.</p><h2>Third-party services</h2><p>Maps, external links and form processing are provided by their respective services. Retailer logos identify stores; they do not guarantee stock in every branch.</p>`}</article></section>`;}
function footer(){return `<div class="footer-main"><div><a class="logo" href="/" aria-label="Proctor and Allan home"><img decoding="async" loading="lazy" src="${A}official-logo.webp" alt="Proctor & Allan"></a><p class="tagline">THE HOME OF HEALTHIER FOODS</p><p>Under Astitva Foods</p></div><div><h3>Explore</h3><a href="/">Home</a><a href="/products">Our Foods</a><a href="/recipes">Recipes</a><a href="/health-and-nutrition">Health & Nutrition</a></div><div><h3>Our Company</h3><a href="/story">Our Story</a><a href="/farmers">Farm to Table</a><a href="/where-to-buy">Where to Buy</a><a href="/contact">Contact Us</a></div><div><h3>Get in Touch</h3><a href="${mapURL}" target="_blank" rel="noopener">Manguo Road, Limuru, Kenya</a><a href="mailto:info@proctorandallan.com">info@proctorandallan.com</a><a href="mailto:sales@proctorandallan.com">sales@proctorandallan.com</a><a href="tel:+254727065933">+254 727 065 933</a><p>Local & international enquiries welcome.</p></div></div><div class="footer-legal"><span>© ${new Date().getFullYear()} Proctor & Allan. All rights reserved.</span><div><a href="/privacy">Privacy</a><a href="/terms">Website Terms</a></div></div>`;}
function notFound(){return `<section class="section detail-page">${eye('PROCTOR & ALLAN')}<h1>Let’s find your way.</h1><p class="lede">This page isn’t available. Explore the range or return to the home page.</p><p style="margin-top:30px">${btn('/','Back home')} ${link('/products','Our foods')}</p></section>`;}
function fitPhotos(){const fit=f=>{const im=$('img',f);if(!im?.naturalWidth)return;const [x,y,w,h]=f.dataset.crop.split(',').map(Number),nw=im.naturalWidth,nh=im.naturalHeight,cw=f.clientWidth,ch=f.clientHeight;const scale=Math.min(cw/(nw*w),ch/(nh*h));let left=(cw-nw*w*scale)/2,top=(ch-nh*h*scale)/2;if(f.closest('.hero-art')){left=cw-nw*w*scale;top=0;}else if(f.parentElement.classList.contains('image-left'))left=0;else if(f.parentElement.classList.contains('image-right'))left=cw-nw*w*scale;Object.assign(im.style,{width:nw*scale+'px',height:nh*scale+'px',left:left-nw*x*scale+'px',top:top-nh*y*scale+'px'});};const obs=new ResizeObserver(es=>es.forEach(e=>fit(e.target)));$$('[data-crop]').forEach(f=>{if(f.dataset.fitted)return;f.dataset.fitted='true';const im=$('img',f);im.addEventListener('load',()=>fit(f));obs.observe(f);fit(f);});}
function bind(){fitPhotos();let foodFilter='All',recipeFilter='All recipes';const applyFoods=()=>{const q=($('#product-search')?.value||'').trim().toLowerCase();const list=products.slice(0,5).filter(p=>(foodFilter==='All'||p.group===foodFilter)&&(p.name+' '+p.desc).toLowerCase().includes(q));$('#product-grid').innerHTML=prefixHTML(list.map(productCard).join(''));fitPhotos();$('#product-status').textContent=list.length?'': 'No products match this search. Try another name.';};$$('[data-food-filter]').forEach(b=>b.addEventListener('click',()=>{foodFilter=b.dataset.foodFilter;$$('[data-food-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));applyFoods();}));$('#product-search')?.addEventListener('input',applyFoods);
const applyRecipes=()=>{const q=($('#recipe-search')?.value||'').trim().toLowerCase();const list=R.filter(r=>(recipeFilter==='All recipes'||r.category===recipeFilter)&&(r.name+' '+r.product+' '+r.ingredients.join(' ')).toLowerCase().includes(q));$('#recipes-grid').innerHTML=prefixHTML(list.map(recipeCard).join(''));$('#recipe-status').textContent=list.length?'Times are estimates. Follow the full recipe and your current pack instructions.':'No recipes match this search. Try another ingredient.';};$$('[data-recipe-filter]').forEach(b=>b.addEventListener('click',()=>{recipeFilter=b.dataset.recipeFilter;$$('[data-recipe-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));applyRecipes();}));$('#recipe-search')?.addEventListener('input',applyRecipes);
const p=products.find(p=>path==='/products/'+p.id);$$('[data-product-tab]').forEach(b=>{const activate=()=>{$$('[data-product-tab]').forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1;});$('#product-panel').innerHTML=productInfo(p,Number(b.dataset.productTab));$('#product-panel').setAttribute('aria-labelledby',b.id);};b.addEventListener('click',activate);b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=$$('[data-product-tab]');let i=all.indexOf(b);i=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;all[i].click();all[i].focus();}});});
const form=$('#enquiry-form');if(form){const type=$('#enquiry-type');const update=()=>{const sales=['business','international'].includes(type.value);form.action='https://formsubmit.co/'+(sales?'sales':'info')+'@proctorandallan.com';form.querySelector('[name=_subject]').value='Proctor & Allan — '+type.options[type.selectedIndex].text;};const topic=location.pathname==='/international'?'international':new URLSearchParams(location.search).get('topic');if(['business','international','feedback'].includes(topic))type.value=topic;type.addEventListener('change',update);update();$('#form-next').value=location.origin+SITE_BASE+'/contact/?sent=1#contact-form';form.addEventListener('submit',()=>{update();});if(new URLSearchParams(location.search).get('sent')==='1')$('#form-status').textContent='Thank you. Your enquiry has been submitted.';}
$$('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));
}
async function init(){if(path.startsWith('/products/')){try{const r=await fetch(SITE_BASE+'/nutrition-data.json');if(!r.ok)throw Error('nutrition');nutrition=await r.json();}catch{nutrition={products:Object.fromEntries(products.map(p=>[p.id,{ingredients:[],allergens:[],nutrients:[],pending:true}]))};}}
const p=products.find(p=>path==='/products/'+p.id),r=R.find(r=>path==='/recipes/'+r.id),a=articles.find(a=>path==='/health-and-nutrition/'+a.id);const routes={'/':home,'/products':foods,'/recipes':recipesPage,'/story':story,'/farmers':farmers,'/health-and-nutrition':nutritionPage,'/where-to-buy':whereToBuy,'/contact':contact,'/privacy':()=>legal('privacy'),'/terms':()=>legal('terms')};const render=p?()=>productDetail(p):r?()=>recipeDetail(r):a?()=>articleDetail(a):routes[path]||notFound;$('#main').innerHTML=prefixHTML(render());$('#footer').innerHTML=prefixHTML(footer());const heroImage=Array.from(document.querySelectorAll('#main img')).find(im=>im.getBoundingClientRect().width>0);if(heroImage){heroImage.loading='eager';heroImage.fetchPriority='high';}document.title=(p?.name||r?.name||a?.title||navItems.find(n=>n[0]===path)?.[1]||'Proctor & Allan')+' | Proctor & Allan';$('#navigation').innerHTML=prefixHTML(navItems.map(([url,t])=>`<a href="${url}"${url===path||(url!=='/'&&path.startsWith(url+'/'))?' aria-current="page"':''}>${t}</a>`).join(''));bind();if(location.hash){requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());}if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');io.unobserve(e.target);}}),{threshold:.06});$$('.section-head,.split .copy').forEach(e=>io.observe(e));}}
let lastY=0;window.addEventListener('scroll',()=>{const y=window.scrollY,h=$('#header');if(!h.classList.contains('menu-open')){if(y>120&&y>lastY+3)h.classList.add('hidden');else if(y<lastY-3||y<90)h.classList.remove('hidden');}h.classList.toggle('scrolled',y>40);lastY=y;},{passive:true});$('.menu-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open);$('#header').classList.toggle('menu-open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#header').classList.remove('menu-open');$('.menu-toggle').setAttribute('aria-expanded','false');}});init();
new MutationObserver(fitPhotos).observe(document.querySelector("#main"),{childList:true,subtree:true});
